SELECT CAST(COUNT(CASE WHEN p.start_time BETWEEN (CURRENT_TIME - INTERVAL '72 hours') AND CURRENT_TIME AND p.end_time IS NULL AND p.drug_code = 'GLP-1' THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS proportion_started_within_72h, CAST(COUNT(CASE WHEN p.start_time BETWEEN (CURRENT_TIME - INTERVAL '48 hours') AND CURRENT_TIME AND p.end_time IS NULL AND p.drug_code = 'GLP-1' THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS proportion_started_within_48h, CAST(COUNT(CASE WHEN p.start_time BETWEEN (CURRENT_TIME - INTERVAL '72 hours') AND CURRENT_TIME AND p.end_time IS NULL AND p.drug_code = 'GLP-1' THEN 1 END) AS FLOAT) - CAST(COUNT(CASE WHEN p.start_time BETWEEN (CURRENT_TIME - INTERVAL '48 hours') AND CURRENT_TIME AND p.end_time IS NULL AND p.drug_code = 'GLP-1' THEN 1 END) AS FLOAT) AS net_change FROM physionet-data.mimiciv_3_1_hosp.patients pt JOIN physionet-data.mimiciv_3_1_hosp.prescriptions p ON pt.subject_id = p.subject_id WHERE pt.gender = 'M' AND pt.anchor_age BETWEEN 45 AND 55 AND pt.hadm_id IN (SELECT hadm_id FROM physionet-data.mimiciv_3_1_hosp.diagnoses_icd WHERE icd_code IN ('281', '3500'));